 async function pickPhoto(replaceId){try{const r=await ImagePicker.launchImageLibraryAsync({mediaTypes:["images"],allowsEditing:false,quality:1});if(r.canceled||!r.assets?.[0]?.uri)return;const a=r.assets[0];if(replaceId)updateImage(replaceId,{uri:a.uri});else{const id=String(Date.now());setImages(old=>[...old,{id,uri:a.uri,name:a.fileName||"Photo overlay",startTime:0,duration:Math.min(5,clipDuration),x:.5,y:.5,scale:1,rotation:0,opacity:1}]);setSelectedId(id);}}catch(e){Alert.alert("Photo error",e.message||"Photo select nahi ho saki.");}}
