    {texts.filter(x=>position>=x.startTime&&position<=x.startTime+x.duration).map(x=><Text key={x.id} style={{position:"absolute",left:`${x.x*100}%`,top:`${x.y*100}%`,color:x.color,fontSize:Math.max(14,Math.min(28,x.fontSize/2)),fontWeight:x.fontWeight||"900",fontFamily:x.fontFamily,fontStyle:x.fontStyle,backgroundColor:x.backgroundColor||"rgba(0,0,0,.35)",padding:5}}>{x.text}</Text>)}
